mapper.select:
SELECT X.TITLE ,X.PRESS FROM ( SELECT DISTINCT ON (N.TITLE) N.TITLE ,N.PRESS ,N.PUB_DATE FROM T_NEWS N WHERE 1=1 AND N.PUB_DATE >= #{fromAt}
AND N.STOCK_ID = #{stockId}
AND N.CATEGORY = 'MARKET'
AND
N.TITLE ILIKE '%' || #{keyword} || '%'
ORDER BY N.TITLE ,N.PUB_DATE DESC ) X ORDER BY X.PUB_DATE DESC LIMIT #{limit}

mapper.insert:
INSERT INTO T_NEWS_SUMMARY (
TARGET_KEY
,CATEGORY
,STOCK_ID
,SUMMARY
,NEWS_COUNT
,SUMMARY_AT
) VALUES (
#{targetKey}
,#{category}
,#{stockId}
,#{summary}
,#{newsCount}
,#{summaryAt}
)
ON CONFLICT (TARGET_KEY) DO UPDATE
SET SUMMARY    = EXCLUDED.SUMMARY
,NEWS_COUNT = EXCLUDED.NEWS_COUNT
,SUMMARY_AT = EXCLUDED.SUMMARY_AT

mapper.delete:
DELETE FROM T_NEWS_SUMMARY
WHERE 1=1
AND TARGET_KEY = #{targetKey}
